import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import {
  ExactRational as R, applyInventoryValueAdjustmentToHoldings, calculateInventoryValueAdjustment,
  commandId, createBookProtocolState, createBookState, decodeDurableBook, encodeDurableBook as encodeAggregate,
  executeBookCommand, instant, inventoryValueAdjustmentId, localDate, sealCommand, semanticVersion,
  journalId, postingId, lotId, lotHoldingId, resolveJournal,
  type BookState, type DurableBookAggregate, type InventoryValueAdjustmentPolicy,
} from "../src/index.ts";

// Generated by the unmodified kernel before the G1-INV-01 repair. Never regenerate
// this fixture using the implementation under test: it anchors an actual old result.
const legacyBytes = readFileSync(new URL("./data/inventory-adjustment-legacy.json", import.meta.url), "utf8").trim();
const originalResultDigest = "bd43ade0477fab46033ed0172eb8a98f9e26c27d8f990871ee564a89c9a81e4b";
const zero = R.zero();
const one = R.of(1n, 1n);

function encodeDurableBook({ state, protocol }: DurableBookAggregate) {
  return encodeAggregate({ state, protocol });
}

function decode(bytes: string): DurableBookAggregate {
  const result = decodeDurableBook(bytes);
  if (result.disposition !== "decoded") throw new Error(result.message);
  return result.aggregate;
}

function originalCommand(book: DurableBookAggregate) {
  const command = book.protocol.retainedResults[3]!.command;
  if (command.type !== "adjustInventoryValue") throw new Error("Incorrect historical fixture");
  return command;
}

function core(state: BookState, id: string) {
  const at = instant("2026-01-16T14:00:00Z");
  return { id: commandId(id), protocolVersion: semanticVersion("1.0.0"), bookId: state.identity.bookId,
    expectedBookRevision: state.bookRevision, actorId: originalCommand(decode(legacyBytes)).actorId,
    issuedAt: at, completedAt: at, committedAt: at };
}

function replacement(book: DurableBookAggregate, algorithm = "1.0.1") {
  const original = book.state.accountingPolicySnapshot.policies.find((policy) => policy.kind === "inventoryValueAdjustment");
  if (original?.kind !== "inventoryValueAdjustment") throw new Error("Missing value policy");
  const policy: InventoryValueAdjustmentPolicy = { ...original, version: semanticVersion("1.0.1"),
    validFrom: instant("2026-01-16T00:00:00Z"), algorithmVersion: semanticVersion(algorithm),
    capability: { ...original.capability, implementationVersion: semanticVersion(algorithm) } };
  const command = sealCommand({ ...core(book.state, "audit-upgrade-value-policy"), type: "replaceConfiguration" as const,
    expectedConfigurationRevision: book.state.configurationRevision, effectiveOn: localDate("2026-01-16"),
    periods: book.state.periods, admissionSnapshot: book.state.admissionSnapshot, policies: book.state.policies,
    quantizationPolicies: book.state.quantizationPolicies,
    accountingPolicies: book.state.accountingPolicySnapshot.policies.map((item) => item === original ? policy : item) });
  return { policy, command };
}

function upgraded(algorithm = "1.0.1") {
  const legacy = decode(legacyBytes);
  const { policy, command } = replacement(legacy, algorithm);
  const current = executeBookCommand(legacy.state, legacy.protocol, command);
  expect(current.result.disposition).toBe("committed");
  const old = originalCommand(legacy);
  const adjustment = sealCommand({ ...old, ...core(current.state, "audit-value-fixed"), request: { ...old.request,
    id: inventoryValueAdjustmentId("audit-value-fixed"), generatedEffectKey: "audit-value-fixed:journal:0" as never,
    policyVersion: policy.version, policyEffectiveAt: instant("2026-01-16T00:00:00Z"), effectiveOn: localDate("2026-01-16"),
    derivation: { ...old.request.derivation, policyVersion: policy.version } } });
  return { legacy, policy, current, adjustment };
}

function rebuilt(book: DurableBookAggregate): DurableBookAggregate {
  const first = book.state.configurationSnapshots[0]!;
  let current: DurableBookAggregate = { state: createBookState(book.state.identity, first.periods,
    first.admissionSnapshot, first.policies, first.quantizationPolicies, first.accountingPolicySnapshot.policies, first.effectiveAt),
    protocol: createBookProtocolState() };
  for (const retained of book.protocol.retainedResults) {
    current = executeBookCommand(current.state, current.protocol, retained.command);
    expect(current.protocol.retainedResults.at(-1)!.resultHash).toEqual(retained.resultHash);
  }
  return current;
}

describe("ACC-039.2/4/5, ACC-030/034/047: versioned inventory account scope", () => {
  test("ACC-038: distinct raw allocation coordinates need prospective identity semantics and preserve prior rejections", () => {
    const legacy = decode(legacyBytes), first = legacy.state.configurationSnapshots[0]!;
    let book: DurableBookAggregate = { state: createBookState(legacy.state.identity, first.periods,
      first.admissionSnapshot, first.policies, first.quantizationPolicies, first.accountingPolicySnapshot.policies, first.effectiveAt),
      protocol: createBookProtocolState() };
    const activated = executeBookCommand(book.state, book.protocol, legacy.protocol.retainedResults[0]!.command);
    expect(activated.result.disposition).toBe("committed");
    book = activated;
    const source = legacy.protocol.retainedResults[1]!.command;
    if (source.type !== "postJournal" || source.lotOperations?.[0]?.type !== "acquire") throw new Error("Missing acquisition fixture");
    const acquisition = source.lotOperations[0];
    for (const [index, [lotName, holdingName]] of ([["raw:lot", "holding"], ["raw", "lot:holding"]] as const).entries()) {
      const id = `raw-source-${index}`;
      const journal = { ...source.resolved.journal, id: journalId(id),
        postings: source.resolved.journal.postings.map((posting, ordinal) => ({ ...posting, id: postingId(`${id}-${ordinal}`) })) };
      const resolved = resolveJournal(journal, book.state.policies, book.state.identity.ownerId,
        source.resolved.quantizationPolicy, source.resolved.exactBookValues);
      if (!("journal" in resolved)) throw new Error("Acquisition did not resolve");
      const command = sealCommand({ ...source, id: commandId(id), expectedBookRevision: book.state.bookRevision, resolved,
        lotOperations: [{ ...acquisition, journalPostingId: journal.postings[0]!.id,
          lot: { ...acquisition.lot, id: lotId(lotName) },
          holding: { ...acquisition.holding, id: lotHoldingId(holdingName), lotId: lotId(lotName) } }] });
      const posted = executeBookCommand(book.state, book.protocol, command);
      expect(posted.result.disposition).toBe("committed");
      book = posted;
    }
    expect(book.state.lotHoldings.map((holding) => `${holding.lotId}:${holding.id}`)).toEqual(["raw:lot:holding", "raw:lot:holding"]);
    const rejectedReceipts = [];
    for (const algorithm of ["1.0.0", "1.0.1", "1.0.2"]) {
      const { policy, command: replace } = replacement(book, algorithm);
      const configured = executeBookCommand(book.state, book.protocol, sealCommand({ ...replace,
        id: commandId(`raw-policy-${algorithm}`), accountingPolicies: replace.accountingPolicies.map((item) =>
          item.kind === "inventoryValueAdjustment" ? { ...item, version: semanticVersion(algorithm) } : item) }));
      expect(configured.result.disposition).toBe("committed");
      const old = originalCommand(legacy);
      const command = sealCommand({ ...old, ...core(configured.state, `raw-adjustment-${algorithm}`), request: { ...old.request,
        id: inventoryValueAdjustmentId(`raw-adjustment-${algorithm}`), generatedEffectKey: `raw-adjustment-${algorithm}:journal:0` as never,
        exactSourceAmount: R.of(2n, 1n), policyVersion: semanticVersion(algorithm),
        policyEffectiveAt: policy.validFrom, effectiveOn: localDate("2026-01-16"),
        derivation: { ...old.request.derivation, policyVersion: semanticVersion(algorithm) },
        allocations: book.state.lotHoldings.map((holding, index) => ({ ...old.request.allocations[0]!,
          ordinal: BigInt(index + 1), lotId: holding.lotId, holdingId: holding.id })) } });
      const result = executeBookCommand(configured.state, configured.protocol, command);
      expect(result.result.disposition).toBe(algorithm === "1.0.2" ? "committed" : "rejected");
      if (algorithm !== "1.0.2") {
        expect(result.result.diagnostics[0]?.code).toBe("inventory_value_adjustment_violation");
        expect(result.state).toBe(configured.state);
        rejectedReceipts.push({ command, hash: result.result.resultHash });
      } else {
        expect(result.state.lotHoldings.map((holding) => holding.remainingTotalBasis.toString())).toEqual(["11/1", "11/1"]);
        expect(result.state.journals.at(-1)!.journal.postings.map((posting) => posting.bookValue.amount.toString())).toEqual(["2.00", "-2.00"]);
        const duplicate = sealCommand({ ...command, id: commandId("raw-duplicate"), expectedBookRevision: result.state.bookRevision,
          request: { ...command.request, id: inventoryValueAdjustmentId("raw-duplicate"), generatedEffectKey: "raw-duplicate:journal:0" as never,
            allocations: command.request.allocations.map((allocation) => ({ ...command.request.allocations[0]!, ordinal: allocation.ordinal })) } });
        const refused = executeBookCommand(result.state, result.protocol, duplicate);
        expect(refused.result.disposition).toBe("rejected");
        expect(refused.result.diagnostics[0]?.code).toBe("inventory_value_adjustment_violation");
        expect(refused.state).toBe(result.state);
      }
      book = result;
      const encoded = encodeDurableBook(book), restored = decode(encoded);
      for (const receipt of rejectedReceipts) {
        const retry = executeBookCommand(restored.state, restored.protocol, receipt.command);
        expect(retry.result.disposition).toBe("replayed");
        expect(retry.result.resultHash).toEqual(receipt.hash);
        expect(encodeDurableBook(retry)).toBe(encoded);
      }
    }
  });

  test("reexecutes the pre-repair history and preserves its exact rejected receipt", () => {
    expect(JSON.parse(legacyBytes).checksum.digest).toBe("71cf9958ff519a32d738510899d3aec46003bd8e6f91628dab89d2c36c6efd98");
    const legacy = decode(legacyBytes);
    expect(legacy.protocol.retainedResults[3]!.resultHash.digest).toBe(originalResultDigest);
    expect(encodeDurableBook(rebuilt(legacy))).toBe(legacyBytes);
    const retry = executeBookCommand(legacy.state, legacy.protocol, originalCommand(legacy));
    expect(retry.result.disposition).toBe("replayed");
    expect(retry.result.resultHash).toEqual(legacy.protocol.retainedResults[3]!.resultHash);
    expect(encodeDurableBook(retry)).toBe(legacyBytes);
  });

  test("a prospective policy repairs multi-account adjustment without rewriting old outcomes", () => {
    const { legacy, current, adjustment } = upgraded();
    const before = encodeDurableBook(current);
    const next = executeBookCommand(current.state, current.protocol, adjustment);
    expect(next.result.disposition).toBe("committed");
    expect(next.state.bookRevision).toBe(5n);
    expect(next.state.lotHoldings.map((holding) => holding.remainingTotalBasis.toString())).toEqual(["11/1", "10/1"]);
    expect(next.state.lotHoldings.map((holding) => holding.remainingQuantity.toString())).toEqual(["1/1", "1/1"]);
    expect(next.state.lotHoldings[1]).toEqual(current.state.lotHoldings[1]);
    expect(next.state.journals.at(-1)!.journal.postings.map((posting) => [posting.accountId, posting.bookValue.amount.toRational().toString()]))
      .toEqual([["account-inventory", "1/1"], ["account-adjustment", "-1/1"]]);
    expect(encodeDurableBook(current)).toBe(before);
    const restored = decode(encodeDurableBook(next));
    expect(encodeDurableBook(rebuilt(restored))).toBe(encodeDurableBook(next));
    const retry = executeBookCommand(restored.state, restored.protocol, originalCommand(legacy));
    expect(retry.result.disposition).toBe("replayed");
    expect(retry.result.resultHash).toEqual(legacy.protocol.retainedResults[3]!.resultHash);
    expect(retry.result.resultHash.digest).toBe(originalResultDigest);
    expect(encodeDurableBook(retry)).toBe(encodeDurableBook(next));
    const fixedRetry = executeBookCommand(restored.state, restored.protocol, adjustment);
    expect(fixedRetry.result.disposition).toBe("replayed");
    expect(fixedRetry.result.resultHash).toEqual(next.result.resultHash);
  });

  test("a wrong-account target is rejected atomically, even when unrelated holdings are valid", () => {
    const { current, adjustment } = upgraded();
    const target = current.state.lotHoldings[1]!;
    const command = sealCommand({ ...adjustment, request: { ...adjustment.request, allocations: [{
      ...adjustment.request.allocations[0]!, lotId: target.lotId, holdingId: target.id }] } });
    const next = executeBookCommand(current.state, current.protocol, command);
    expect(next.result.disposition).toBe("rejected");
    expect(next.result.diagnostics[0]!.code).toBe("inventory_value_adjustment_violation");
    expect(next.state).toBe(current.state);
    expect(next.protocol.retainedResults.length).toBe(current.protocol.retainedResults.length + 1);
    expect(decodeDurableBook(encodeDurableBook(next)).disposition).toBe("decoded");
  });

  test("complete cross-account lot holdings prevent false disposed-lot catch-up", () => {
    const { current, adjustment } = upgraded();
    const a = current.state.lotHoldings[0]!;
    const b = { ...current.state.lotHoldings[1]!, lotId: a.lotId };
    const depleted = { ...a, remainingQuantity: zero, remainingTotalBasis: zero, remainingValuationAllowance: zero, remainingCarryingAmount: zero };
    const request = { ...adjustment.request, allocations: [{ ordinal: 1n, lotId: a.lotId,
      remainingBasisChange: zero, recognizedCostChange: one, remainingValuationAllowanceChange: zero }] };
    const calculate = (holdings: typeof current.state.lotHoldings) => calculateInventoryValueAdjustment(
      current.state.accountingPolicySnapshot.policies, current.state.identity.bookId, current.state.identity.functionalCommodityId,
      current.state.lots, holdings, request);
    const live = calculate([depleted, b]);
    expect(live.disposition).toBe("rejected");
    if (live.disposition !== "rejected") throw new Error("A live transferred lot was treated as disposed");
    expect(live.diagnostics[0]!.path).toBe("command.inventoryValueAdjustment.allocations");
    const allDepleted = [depleted, { ...b, remainingQuantity: zero, remainingTotalBasis: zero, remainingValuationAllowance: zero, remainingCarryingAmount: zero }];
    const disposed = calculate(allDepleted);
    expect(disposed.disposition).toBe("draft");
    if (disposed.disposition !== "draft") throw new Error("Disposed lot catch-up rejected");
    expect(disposed.draft.journals[0]!.postings.map((posting) => [posting.accountId, posting.exactBookValue.toString()]))
      .toEqual([["account-expense", "1/1"], ["account-adjustment", "-1/1"]]);
    expect(applyInventoryValueAdjustmentToHoldings(allDepleted, request.allocations)).toEqual(allDepleted);
    // Unrelated rows still need valid book/lot/value invariants, not blind filtering.
    expect(calculate([{ ...depleted, bookId: "foreign-book" as never }, allDepleted[1]!]).disposition).toBe("rejected");
  });

  test("unknown algorithms fail both configuration and standalone calculator admission", () => {
    const legacy = decode(legacyBytes);
    const { policy, command } = replacement(legacy, "9.9.9");
    const next = executeBookCommand(legacy.state, legacy.protocol, command);
    expect(next.result.disposition).toBe("rejected");
    expect(next.result.diagnostics[0]!.code).toBe("policy_ambiguity");
    expect(next.state).toBe(legacy.state);
    const request = { ...originalCommand(legacy).request, policyVersion: policy.version,
      policyEffectiveAt: instant("2026-01-16T00:00:00Z"), derivation: { ...originalCommand(legacy).request.derivation, policyVersion: policy.version } };
    const result = calculateInventoryValueAdjustment(command.accountingPolicies, legacy.state.identity.bookId,
      legacy.state.identity.functionalCommodityId, legacy.state.lots, legacy.state.lotHoldings, request);
    expect(result.disposition).toBe("rejected");
    if (result.disposition !== "rejected") throw new Error("Unknown algorithm executed");
    expect(result.diagnostics[0]!.path).toBe("command.policy");
  });

  test.each(["1.0.1", "1.0.2"])("algorithm %s preserves exact arithmetic for every adjustment kind", (algorithm) => {
    const { current, policy, adjustment } = upgraded(algorithm);
    const kinds = ["directlyAttributableCost", "productionOverhead", "purchaseRebate", "writeDown", "writeDownReversal"] as const;
    const completePolicy = { ...policy, allowedKinds: kinds };
    const policies = current.state.accountingPolicySnapshot.policies.map((item) => item.kind === "inventoryValueAdjustment" ? completePolicy : item);
    for (const [kind, change, priorAllowance, expectedBasis, expectedAllowance] of [
      ["directlyAttributableCost", 1n, 0n, "11/1", "0/1"],
      ["productionOverhead", 1n, 0n, "11/1", "0/1"],
      ["purchaseRebate", -1n, 0n, "9/1", "0/1"],
      ["writeDown", -2n, 0n, "10/1", "-2/1"],
      ["writeDownReversal", 1n, -2n, "10/1", "-1/1"],
    ] as const) {
      const isAllowance = kind === "writeDown" || kind === "writeDownReversal";
      const amount = R.of(change, 1n);
      const holdings = current.state.lotHoldings.map((holding, index) => index === 0 ? { ...holding,
        remainingValuationAllowance: R.of(priorAllowance, 1n), remainingCarryingAmount: R.of(10n + priorAllowance, 1n) } : holding);
      const allocations = [{ ...adjustment.request.allocations[0]!, remainingBasisChange: isAllowance ? zero : amount,
        remainingValuationAllowanceChange: isAllowance ? amount : zero }];
      const result = calculateInventoryValueAdjustment(policies, current.state.identity.bookId, current.state.identity.functionalCommodityId,
        current.state.lots, holdings, { ...adjustment.request, kind, exactSourceAmount: amount, allocations });
      expect(result.disposition).toBe("draft");
      if (result.disposition !== "draft") throw new Error("Adjustment kind rejected");
      expect(result.draft.journals[0]!.postings.map((posting) => posting.exactBookValue.toString())).toEqual([amount.toString(), amount.negate().toString()]);
      const next = applyInventoryValueAdjustmentToHoldings(holdings, allocations);
      expect(next[0]!.remainingTotalBasis.toString()).toBe(expectedBasis);
      expect(next[0]!.remainingValuationAllowance.toString()).toBe(expectedAllowance);
      expect(next[0]!.remainingQuantity.toString()).toBe("1/1");
      expect(next[1]).toEqual(holdings[1]);
    }
  });
});
